  for (const u of units) { if (size + u.size > 40000 && chunks[chunks.length - 1].length) { chunks.push([]); size = 0; } chunks[chunks.length - 1].push(u); size += u.size; }
  const p = part || 0, out = { schema: PS_SCHEMA, part: p, parts: chunks.length, groups: {} };
  if (p === 0) Object.assign(out, { source: exp.source, digest: cur });
  for (const u of chunks[p]) { const g = out.groups[u.k] || (out.groups[u.k] = { buckets: [], items: [] }); g.buckets.push(u.i); g.items.push(...u.items); }
